implementation:
#include <windows.h>

void PositionCloseButton(HWND hwndFrame) {
    // Retrieve the close button handle
    HWND hwndCloseButton = GetDlgItem(hwndFrame, IDC_CLOSE);
    if (hwndCloseButton == NULL) {
        return;
    }

    // Get the preferred size of the close button
    RECT rectCloseButton = {0};
    GetWindowRect(hwndCloseButton, &rectCloseButton);

    // Calculate the size of the frame window
    RECT rectFrame = {0};
    GetWindowRect(hwndFrame, &rectFrame);

    // Calculate the caption height (approximate)
    int captionHeight = GetSystemMetrics(SM_CYCAPTION);

    // Calculate the vertical and horizontal offsets
    int verticalOffset = (rectFrame.bottom - rectFrame.top - rectCloseButton.bottom + rectCloseButton.top) / 2;
    int horizontalOffset = (rectFrame.right - rectFrame.left - rectCloseButton.right + rectCloseButton.left) / 2;

    // Adjust the position of the close button
    SetWindowPos(hwndCloseButton, NULL, horizontalOffset, verticalOffset, 0, 0, SWP_NOSIZE | SWP_NOZORDER);
}
